#!/usr/bin/env node
/**
 * @purpose Standalone CLI runner for the Antigravity YOLO Bridge.
 * @rationale Enables local execution of arbitrary markdown instructions or commands outside the OpenCode server lifecycle.
 * @preconditions Node.js runtime >= 22.0.0; valid workspace directory.
 * @invariants Traps OS termination signals (SIGINT, SIGTERM) and guarantees lockfile release upon termination.
 */
import { existsSync } from 'node:fs';
import { resolve } from 'node:path';
import { executeInstructionViaAcp } from './acp-engine.js';
import { loadBridgeConfig } from './config.js';
import { resolveInstruction } from './instruction-resolver.js';
import { WorkspaceLock } from './lock.js';
import { loadOpenCodeMcpServers } from './mcp-bridge.js';
/**
 * @purpose Formats an ExecutionReport into a high-signal human-readable string.
 * @rationale Renders concise execution metadata, executed actions, implementation summaries, and stderr diagnostics.
 * @preconditions report must be an ExecutionReport object.
 * @param report Execution result report.
 * @returns Multi-line formatted summary.
 * @throws Never throws.
 * @invariants Pure string formatting; O(n) where n is log entries count.
 */
export function formatReport(report) {
    const lines = [
        `Status      : ${report.ok ? `SUCCESS (${report.stopReason ?? 'end_turn'})` : `FAILED — ${report.error ?? 'Unknown error'}`}`,
        `Session ID  : ${report.sessionId ?? '-'}`,
        `Model/Mode  : ${report.activeModel ?? '-'} / ${report.activeMode ?? '-'}`,
        `Plan Source : ${report.planSource} (${report.planSha256.slice(0, 12)})`,
        `Duration    : ${(report.durationMs / 1000).toFixed(2)}s | Tool Calls: ${report.toolCallCount}`,
    ];
    if (report.toolLogs.length > 0) {
        lines.push('', '=== Executed Actions ===', ...report.toolLogs);
    }
    if (report.finalOutput) {
        lines.push('', '=== Implementation Summary ===', report.finalOutput);
    }
    if (!report.ok && report.stderrLogs.length > 0) {
        lines.push('', '=== Diagnostics (stderr) ===', ...report.stderrLogs.slice(-20));
    }
    return lines.join('\n');
}
/**
 * @purpose Main CLI execution procedure.
 * @rationale Binds process signals, handles CLI arguments, acquires workspace lock, and invokes ACP engine.
 * @preconditions Valid host process runtime.
 * @returns Promise resolving to void.
 * @throws Rejections handled and reported to process.stderr with exitCode 1.
 * @invariants Sets process.exitCode according to execution success.
 */
export async function main() {
    const cwd = process.cwd();
    const targetArg = process.argv[2];
    const userArgs = process.argv.slice(3).join(' ').trim();
    const config = loadBridgeConfig(cwd);
    if (!targetArg || targetArg === '--help' || targetArg === '-h') {
        const isPlanPresent = config.planPaths.some((p) => existsSync(resolve(cwd, p)));
        if (!isPlanPresent && targetArg) {
            process.stdout.write(`${[
                'Usage: agy-yolo-bridge <commandName|path/to/file.md> [arguments...]',
                '',
                'Examples:',
                '  agy-yolo-bridge ship',
                '  agy-yolo-bridge audit --staged',
                '  agy-yolo-bridge .opencode/commands/review.md PR-101',
            ].join('\n')}\n`);
            process.exitCode = 0;
            return;
        }
    }
    const lock = new WorkspaceLock(cwd, config.lockStaleMs);
    const ac = new AbortController();
    const onSignal = () => ac.abort();
    process.on('SIGINT', onSignal);
    process.on('SIGTERM', onSignal);
    lock.acquire();
    try {
        let requestedAgent;
        let finalTarget = targetArg;
        let finalArgs = userArgs;
        if (targetArg?.startsWith('agent:')) {
            requestedAgent = targetArg.slice(6).trim();
            if (userArgs) {
                const firstArgSpace = userArgs.indexOf(' ');
                const candidateTarget = firstArgSpace === -1 ? userArgs : userArgs.slice(0, firstArgSpace).trim();
                if (candidateTarget.endsWith('.md') || candidateTarget.includes('/')) {
                    finalTarget = candidateTarget;
                    finalArgs = firstArgSpace === -1 ? '' : userArgs.slice(firstArgSpace + 1).trim();
                }
                else {
                    finalTarget = undefined;
                }
            }
            else {
                finalTarget = undefined;
            }
        }
        const isFile = finalTarget ? finalTarget.endsWith('.md') || finalTarget.includes('/') : false;
        const instruction = resolveInstruction(cwd, config, {
            commandName: isFile ? undefined : finalTarget,
            explicitPath: isFile ? finalTarget : undefined,
            agentName: requestedAgent,
            userArgs: finalArgs,
        });
        const mcpServers = config.loadOpenCodeMcp ? await loadOpenCodeMcpServers(cwd) : [];
        const report = await executeInstructionViaAcp({
            cwd,
            config,
            instruction,
            customSystemPrompt: config.useCustomSystemPrompt ? instruction.systemPrompt : undefined,
            mcpServers,
            abortSignal: ac.signal,
            onEvent: (ev) => {
                if (ev.type === 'status' || ev.type === 'tool_start') {
                    process.stderr.write(`[agy] ${ev.summary}\n`);
                }
            },
        });
        process.stdout.write(`${formatReport(report)}\n`);
        process.exitCode = report.ok ? 0 : 1;
    }
    finally {
        process.off('SIGINT', onSignal);
        process.off('SIGTERM', onSignal);
        lock.release();
    }
}
// Invoke main only when executed directly via CLI
if (process.argv[1] && (process.argv[1].endsWith('cli.js') || process.argv[1].endsWith('cli.ts'))) {
    main().catch((err) => {
        process.stderr.write(`[agy-yolo-bridge] Fatal: ${err instanceof Error ? err.message : String(err)}\n`);
        process.exit(1);
    });
}

/**
 * @purpose OpenCode v2 server plugin implementation for the Antigravity YOLO Bridge.
 * @rationale Dynamically registers OpenCode commands from any *.md instruction files, bridges OpenCode MCP servers to Antigravity ACP, overrides default system prompts with OpenCode instructions, and provides universal ad-hoc command execution.
 * @preconditions Running within an OpenCode server or test environment providing the @opencode/plugin Context contract.
 * @invariants Manages exclusive workspace locking, prevents zombie processes, and guarantees deterministic cleanup upon plugin disposal.
 */
import { existsSync, readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { Plugin } from '@opencode/plugin';
import { Schema } from 'effect';
import { executeInstructionViaAcp } from './acp-engine.js';
import { loadBridgeConfig } from './config.js';
import { parseFrontmatter } from './frontmatter.js';
import { discoverCommandMarkdownFiles, resolveInstruction } from './instruction-resolver.js';
import { WorkspaceLock } from './lock.js';
import { loadOpenCodeMcpServers } from './mcp-bridge.js';
/**
 * @purpose Executes any resolved instruction or command pipeline end-to-end within the target workspace.
 * @rationale Coordinates configuration loading, OpenCode MCP bridging, custom system prompt injection, and ACP execution under robust error handling.
 * @preconditions cwd must be a valid directory path string.
 * @param cwd Current working directory of the workspace.
 * @param args Invocation arguments including command name, explicit path, user arguments, model overrides, and progress callbacks.
 * @returns Formatted summary string detailing execution status, duration, actions, and output.
 * @throws Error if workspace locking fails, instruction cannot be resolved, or ACP execution terminates with failure.
 * @invariants Guarantees workspace lock release in all failure and completion branches via finally block.
 */
export async function runUniversalPipeline(cwd, args = {}) {
    const overrides = {};
    if (args.model)
        overrides.model = args.model;
    if (args.thoughtLevel)
        overrides.thoughtLevel = args.thoughtLevel;
    if (args.timeoutMs !== undefined)
        overrides.maxExecutionTimeoutMs = args.timeoutMs;
    const config = loadBridgeConfig(cwd, overrides);
    const lock = new WorkspaceLock(cwd, config.lockStaleMs);
    lock.acquire();
    try {
        // 1. Resolve instruction and custom system prompt from OpenCode *.md
        const instruction = resolveInstruction(cwd, config, {
            commandName: args.commandName,
            explicitPath: args.explicitPath,
            inlineText: args.inlineText,
            userArgs: args.userArgs,
            agentName: args.agentName,
        });
        // 2. Load MCP servers from OpenCode (context and config)
        const mcpServers = config.loadOpenCodeMcp
            ? await loadOpenCodeMcpServers(cwd, args.openCodeCtxMcp)
            : [];
        // 3. Execute instruction via ACP supervisor
        const report = await executeInstructionViaAcp({
            cwd,
            config,
            instruction,
            customSystemPrompt: config.useCustomSystemPrompt ? instruction.systemPrompt : undefined,
            mcpServers,
            abortSignal: args.abortSignal,
            onEvent: (ev) => {
                if (ev.type === 'status' || ev.type === 'tool_start' || ev.type === 'tool_update') {
                    args.onProgress?.(ev.summary);
                }
            },
        });
        if (!report.ok) {
            const errDetail = report.error ?? 'unknown failure';
            const diag = report.stderrLogs.length > 0
                ? `\nDiagnostics:\n${report.stderrLogs.slice(-10).join('\n')}`
                : '';
            throw new Error(`Execution failed (${errDetail}). Tool calls executed: ${report.toolCallCount}.${diag}`);
        }
        const header = [
            `Execution completed in ${(report.durationMs / 1000).toFixed(1)}s`,
            `Command: /${instruction.commandName} | Agent: ${instruction.agentName ?? 'default'} | Model: ${report.activeModel ?? 'default'} | Mode: ${report.activeMode ?? 'accept-edits'} | Actions: ${report.toolCallCount} | OpenCode MCP Servers: ${mcpServers.length}`,
        ].join('\n');
        const actionsBlock = report.toolLogs.length > 0 ? `\n\nExecuted Actions:\n${report.toolLogs.join('\n')}` : '';
        const summaryBlock = report.finalOutput ? `\n\nExecution Summary:\n${report.finalOutput}` : '';
        return `${header}${actionsBlock}${summaryBlock}`;
    }
    finally {
        lock.release();
    }
}
/**
 * Backward-compatible pipeline runner for implementation plan execution.
 */
export async function runShipPipeline(cwd, args = {}) {
    return runUniversalPipeline(cwd, {
        commandName: 'ship',
        explicitPath: args.planPath,
        inlineText: args.inlinePlanText,
        model: args.model,
        thoughtLevel: args.thoughtLevel,
        timeoutMs: args.timeoutMs,
        abortSignal: args.abortSignal,
        onProgress: args.onProgress,
    });
}
export const id = 'agy-yolo-bridge';
const pluginDefinition = Plugin.define({
    id,
    async setup(ctx) {
        const workspaceDir = typeof ctx.location?.directory === 'string' && ctx.location.directory.length > 0
            ? ctx.location.directory
            : process.cwd();
        if (ctx.storage && typeof ctx.storage.set === 'function') {
            await ctx.storage.set('ready', true);
        }
        const config = loadBridgeConfig(workspaceDir);
        const disposers = [];
        // Discover all markdown command files in workspace (.opencode/commands/*.md, etc.)
        const discoveredCommands = discoverCommandMarkdownFiles(workspaceDir, config.commandsDir);
        // Register commands in OpenCode v2 Command domain
        if (ctx.command && typeof ctx.command.transform === 'function') {
            const reg = await ctx.command.transform((editor) => {
                // 1. Dynamically register all discovered *.md commands
                for (const [cmdName, filePath] of discoveredCommands.entries()) {
                    let description = `Execute /${cmdName} autonomous instructions via Antigravity`;
                    if (existsSync(filePath)) {
                        try {
                            const raw = readFileSync(filePath, 'utf8');
                            const { metadata } = parseFrontmatter(raw);
                            if (metadata.description) {
                                description = metadata.description;
                            }
                        }
                        catch {
                            // Ignore frontmatter read error for description
                        }
                    }
                    editor.add({
                        name: cmdName,
                        description,
                        execute: async (invocation) => {
                            const userArgs = invocation.prompt?.text?.trim();
                            const reportText = await runUniversalPipeline(workspaceDir, {
                                commandName: cmdName,
                                explicitPath: filePath,
                                userArgs,
                                openCodeCtxMcp: ctx.mcp,
                            });
                            if (ctx.session &&
                                typeof ctx.session.synthetic === 'function' &&
                                invocation.sessionID) {
                                try {
                                    await ctx.session.synthetic({
                                        sessionID: invocation.sessionID,
                                        text: reportText,
                                        description: `Antigravity /${cmdName} Execution Report`,
                                    });
                                }
                                catch {
                                    // Synthetic error ignored
                                }
                            }
                        },
                    });
                }
                // 2. Ensure /ship is always registered (even if ship.md does not exist yet)
                if (!discoveredCommands.has('ship')) {
                    editor.add({
                        name: 'ship',
                        description: 'Autonomously execute the full implementation plan using Antigravity YOLO mode',
                        execute: async (invocation) => {
                            const rawText = invocation.prompt?.text?.trim();
                            const reportText = await runUniversalPipeline(workspaceDir, {
                                commandName: 'ship',
                                explicitPath: rawText && rawText.length > 0 ? rawText : undefined,
                                userArgs: rawText,
                                openCodeCtxMcp: ctx.mcp,
                            });
                            if (ctx.session &&
                                typeof ctx.session.synthetic === 'function' &&
                                invocation.sessionID) {
                                try {
                                    await ctx.session.synthetic({
                                        sessionID: invocation.sessionID,
                                        text: reportText,
                                        description: 'Antigravity YOLO Bridge Execution Report',
                                    });
