/**
 * @purpose Executes any resolved instruction or command pipeline end-to-end within the target workspace.
 * @rationale Coordinates configuration loading, OpenCode MCP bridging, custom system prompt injection, and ACP execution under robust error handling.
 * @preconditions cwd must be a valid directory path string.
 * @param cwd Current working directory of the workspace.
 * @param args Invocation arguments including command name, explicit path, user arguments, model overrides, and progress callbacks.
 * @returns Formatted summary string detailing execution status, duration, actions, and output.
 * @throws Error if workspace locking fails, instruction cannot be resolved, or ACP execution terminates with failure.
 * @invariants Guarantees workspace lock release in all failure and completion branches via finally block.
 */
export async function runUniversalPipeline(
  cwd: string,
  args: UniversalInvocationArgs = {},
): Promise<string> {
  const overrides: Partial<BridgeConfig> = {};
  if (args.model) overrides.model = args.model;
  if (args.thoughtLevel) overrides.thoughtLevel = args.thoughtLevel;
  if (args.timeoutMs !== undefined) overrides.maxExecutionTimeoutMs = args.timeoutMs;

  const config = loadBridgeConfig(cwd, overrides);
  const lock = new WorkspaceLock(cwd, config.lockStaleMs);

  lock.acquire();
  try {
    // 1. Resolve instruction and custom system prompt from OpenCode *.md
    const instruction = resolveInstruction(cwd, config, {
      commandName: args.commandName,
      explicitPath: args.explicitPath,
      inlineText: args.inlineText,
      userArgs: args.userArgs,
      agentName: args.agentName,
    });

    // 2. Load MCP servers from OpenCode (context and config)
    const mcpServers = config.loadOpenCodeMcp
      ? await loadOpenCodeMcpServers(cwd, args.openCodeCtxMcp)
      : [];

    // 3. Execute instruction via ACP supervisor
    const report = await executeInstructionViaAcp({
      cwd,
      config,
      instruction,
      customSystemPrompt: config.useCustomSystemPrompt ? instruction.systemPrompt : undefined,
      mcpServers,
      abortSignal: args.abortSignal,
      onEvent: (ev) => {
        if (ev.type === 'status' || ev.type === 'tool_start' || ev.type === 'tool_update') {
          args.onProgress?.(ev.summary);
        }
