    if (ctx.tool && typeof ctx.tool.transform === 'function') {
      const reg = await ctx.tool.transform((editor) => {
        // 1. Universal agy_exec tool
        editor.add({
          name: 'agy_exec',
          description:
            'Execute any custom markdown instruction file or command autonomously via Antigravity ACP.',
          input: Schema.Struct({
            command: Schema.optional(Schema.String),
            agent: Schema.optional(Schema.String),
            instructionPath: Schema.optional(Schema.String),
            inlineInstruction: Schema.optional(Schema.String),
            args: Schema.optional(Schema.String),
            prompt: Schema.optional(Schema.String),
            timeoutMs: Schema.optional(Schema.Number),
          }),
          output: Schema.String,
          execute: async (input, toolCtx) => {
            try {
              const typedInput = input as
                | {
                    command?: string | undefined;
                    agent?: string | undefined;
                    instructionPath?: string | undefined;
                    inlineInstruction?: string | undefined;
                    args?: string | undefined;
                    prompt?: string | undefined;
                    timeoutMs?: number | undefined;
                  }
                | undefined;

              const reportText = await runUniversalPipeline(workspaceDir, {
                commandName: typedInput?.command,
                agentName: typedInput?.agent,
                explicitPath: typedInput?.instructionPath,
                inlineText: typedInput?.inlineInstruction ?? typedInput?.prompt,
                userArgs: typedInput?.args,
                timeoutMs: typedInput?.timeoutMs,
                abortSignal: toolCtx?.signal,
                openCodeCtxMcp: ctx.mcp,
                onProgress: (line) => {
                  if (toolCtx?.progress) {
                    toolCtx.progress({ message: line, timestamp: Date.now() }).catch(() => {});
                  }
                },
              });

              return {
                content: reportText,
                output: reportText,
              };
            } catch (err) {
              const errMsg = err instanceof Error ? err.message : String(err);
              return {
                content: `[ERROR] agy_exec failed: ${errMsg}`,
                output: `[ERROR] agy_exec failed: ${errMsg}`,
              };
            }
          },
        });

        // 2. Backward-compatible agy_ship_plan tool
        editor.add({
          name: 'agy_ship_plan',
          description:
            'Execute the complete implementation plan autonomously via Antigravity ACP engine in YOLO mode.',
          input: Schema.Struct({
            planPath: Schema.optional(Schema.String),
            inlinePlanText: Schema.optional(Schema.String),
            timeoutMs: Schema.optional(Schema.Number),
          }),
          output: Schema.String,
          execute: async (input, toolCtx) => {
            try {
              const typedInput = input as
                | {
                    planPath?: string | undefined;
                    inlinePlanText?: string | undefined;
                    timeoutMs?: number | undefined;
                  }
                | undefined;
              const reportText = await runShipPipeline(workspaceDir, {
                planPath: typedInput?.planPath,
                inlinePlanText: typedInput?.inlinePlanText,
                timeoutMs: typedInput?.timeoutMs,
                abortSignal: toolCtx?.signal,
                onProgress: (line) => {
                  if (toolCtx?.progress) {
                    toolCtx.progress({ message: line, timestamp: Date.now() }).catch(() => {});
                  }
                },
              });

              return {
                content: reportText,
                output: reportText,
              };
            } catch (err) {
              const errMsg = err instanceof Error ? err.message : String(err);
              return {
                content: `[ERROR] agy_ship_plan failed: ${errMsg}`,
                output: `[ERROR] agy_ship_plan failed: ${errMsg}`,
              };
            }
          },
        });
      });

      if (reg && typeof reg.dispose === 'function') {
        disposers.push(reg.dispose);
      }
    }

    return async () => {
      for (const dispose of disposers) {
        try {
          await dispose();
        } catch {
          // Ignore disposal errors on plugin unload
        }
      }
    };
  },
});

export const setup = pluginDefinition.setup;

/**
 * @purpose OpenCode v1 compatibility server hook.
 * @rationale Provides backward-compatibility configuration hook for OpenCode v1 environments expecting server() export.
 * @preconditions Running in an OpenCode v1 runtime environment.
 * @param _options Optional OpenCode v1 server options.
 * @returns Object providing config hook with agy and ship commands.
 * @throws Never throws.
 * @invariants Idempotent and side-effect-free configuration generator.
 */
export async function server(_options?: any): Promise<{ config: (config: any) => Promise<void> }> {
  return {
    config: async (config: any) => {
      if (!config.command) config.command = {};
      config.command.agy = {
        description:
          'Execute any custom markdown command or instruction file autonomously via Antigravity',
        template: '/agy $1',
      };
      config.command.ship = {
        description:
          'Autonomously execute the full implementation plan using Antigravity YOLO mode',
        template: '/agy agent:build .agent/handoff/02_TECHNICAL_PLAN.md',
      };
    },
  };
}

export default {
  id: pluginDefinition.id,
  setup: pluginDefinition.setup,
  server,
};
